/**
 * jsi-rs demo app
 *
 * Everything below is a Rust TurboModule defined by a single attribute in
 * native/jsi-demo-module. The import is TypeScript *generated by the Rust
 * macro* at compile time (native/jsi-demo-module/generated/rust-turbo/);
 * importing it bootstraps the `RustTurbo` proxy, which lazily constructs the
 * module and pre-installs its methods on a prototype.
 *
 * @format
 */

import React, {useEffect, useState} from 'react';
import {SafeAreaView, ScrollView, StatusBar, StyleSheet, Text, View} from 'react-native';

// generated by #[RustTurboModule("TurboDemo")] in native/jsi-demo-module —
// importing it triggers the native bindings installer on first use
import {getTurboDemo} from './native/jsi-demo-module/generated/rust-turbo/TurboDemo';
import {getTicker} from './native/jsi-demo-module/generated/rust-turbo/Ticker';

function App(): React.JSX.Element {
  const [rows, setRows] = useState<Array<[string, string]>>([]);
  const [ticks, setTicks] = useState<string>('');
    const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const turbo = getTurboDemo();
        const p = turbo.makePoint('turbo point', 6, 8);
        const out: Array<[string, string]> = [
          ['TurboDemo.version', turbo.version],
          ['TurboDemo.add(19, 23)', String(turbo.add(19, 23))],
          ['TurboDemo.greet("turbo")', turbo.greet('turbo')],
          ['TurboDemo.sumList([1..100])', String(turbo.sumList(Array.from({length: 100}, (_, i) => i + 1)))],
          ['TurboDemo.makePoint(6, 8, ...)', JSON.stringify(p)],
          ['TurboDemo.pointMagnitude(p)', String(turbo.pointMagnitude(p))],
          // async method: the body runs on the jsi-turbo worker pool and
          // the Promise resolves back on the JS thread
          ['await TurboDemo.slowAdd(20, 22)', String(await turbo.slowAdd(20, 22))],

          // P3: zero-copy buffers — a Rust Vec moved into JS as an
          // ArrayBuffer backed by the same memory, then read back in place
          ['TurboDemo.makeBuffer(4096).byteLength', String(turbo.makeBuffer(4096).byteLength)],
          ['TurboDemo.checksum(makeBuffer(4096))', String(turbo.checksum(turbo.makeBuffer(4096)))],

          // P3: nested objects — a non-singleton Rust object held by JS;
          // passing it back yields the same instance (reference semantics)
          ...(() => {
            const c = turbo.createCounter(10);
            c.increment(2);
            c.increment(3);
            return [
              ['Counter.increment(2), (3) → value', String(c.value)],
              ['TurboDemo.readCounter(c)', String(turbo.readCounter(c))],
            ] as Array<[string, string]>;
          })(),

          // proxy diagnostics (P1): registry introspection
          ['RustTurbo.names()', ((globalThis.RustTurbo as unknown as {names(): string[]}) ?? {names: () => []}).names().join(', ')],
          ['RustTurbo.version / buildType', `${(globalThis.RustTurbo as unknown as {version: string}).version} / ${(globalThis.RustTurbo as unknown as {buildType: string}).buildType}`],
        ];
        if (!cancelled) {
          setRows(out);
        }
      } catch (e) {
        if (!cancelled) {
          setError(String(e));
        }
      }
    })();

    // P3: JS callbacks — Rust fires onTick listeners; fireTicksAsync runs
    // on the worker pool and the callback hops back to the JS thread.
    // Verified on iOS + Android (RN 0.88.1): setState inside the callback
    // renders promptly, no setTimeout wrapper needed.
    const ticker = getTicker();
    ticker.onTick(e => {
      if (!cancelled) {
        setTicks(prev => `${prev}${prev ? ', ' : ''}#${e.index}/${e.total}`);
      }
    });
    const listeners = ticker.fireTicks(3);
    setTicks(prev => `${prev} (${listeners} listener)`);
    ticker.fireTicksAsync(6).then(n => {
      if (!cancelled) {
        setTicks(prev => `${prev} [async fired ${n}]`);
      }
    });

    return () => {
      cancelled = true;
    };
  }, []);

  return (
    <SafeAreaView style={styles.background}>
      <StatusBar barStyle="dark-content" />
      <ScrollView contentInsetAdjustmentBehavior="automatic" style={styles.background}>
        <View style={styles.container}>
          <Text style={styles.title}>jsi-rs demo</Text>
          <Text style={styles.subtitle}>
            Every value below was computed in a Rust TurboModule (React Native 0.88.1 + Hermes)
          </Text>
          {/* P3: JS callbacks — the ticker row keeps appending as Rust fires events */}
          <View style={styles.row}>
            <Text style={styles.rowLabel}>Ticker.onTick(fireTicks 3 + async 6)</Text>
            <Text style={styles.rowValue}>{ticks || 'waiting…'}</Text>
          </View>
          {error !== null ? (
            <Text style={styles.error}>TurboDemo failed: {error}</Text>
          ) : rows.length === 0 ? (
            <Text style={styles.rowLabel}>calling TurboDemo…</Text>
          ) : (
            <>
              {rows.map(([label, value]) => (
                <View key={label} style={styles.row}>
                  <Text style={styles.rowLabel}>{label}</Text>
                  <Text style={styles.rowValue}>{value}</Text>
                </View>
              ))}
            </>
          )}
        </View>
      </ScrollView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  background: {
    backgroundColor: '#fff',
  },
  error: {
    fontSize: 16,
    color: '#c00',
    marginTop: 12,
  },
  container: {
    padding: 24,
    gap: 8,
  },
  title: {
    fontSize: 28,
    fontWeight: '700',
    marginBottom: 4,
    color: '#000',
  },
  subtitle: {
    fontSize: 14,
    color: '#666',
    marginBottom: 20,
  },
  row: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    paddingVertical: 10,
    borderBottomWidth: StyleSheet.hairlineWidth,
    borderBottomColor: '#ddd',
    gap: 12,
  },
  rowLabel: {
    fontSize: 14,
    color: '#333',
    flexShrink: 1,
  },
  rowValue: {
    fontSize: 14,
    fontWeight: '600',
    color: '#0a7',
    flexShrink: 1,
    textAlign: 'right',
  },
});

export default App;
